      const baseSpeed = 112 + Math.min(108, engine.time * 2.4);
      const speed = baseSpeed + (boostTimer > 0 ? 95 : 0);
      scrollX += speed * dt;
      distAcc += speed * dt;
      if (distAcc >= 35) { distAcc -= 35; engine.score(1); }

      const grounded = y >= GROUND_Y - 26;
