      g.circ(232, 106, 24, P.accent2);
      g.circ(232, 106, 14, 7);
      for (let i = 0; i < 16; i++) {
        const sx = ((i * 53 - (scrollX * 0.12) | 0) % 320 + 320) % 320;
        g.pset(sx, 22 + ((i * 19) % 44), i % 2 === 0 ? 7 : P.accent2);
      }
      for (let x = 0; x < 320; x += 4) {
        const fh = 116 + Math.round(Math.sin((x + scrollX * 0.25) * 0.025) * 12);
