        g.rect(x, fh, 4, 2, P.fg);
        const nh = 134 + Math.round(Math.sin((x + scrollX * 0.5) * 0.035 + 2) * 9);
        g.rect(x, nh, 4, GROUND_Y - nh, 18);
        g.rect(x, nh, 4, 2, P.accent1);
      }
      const turfTop = vibe === "cosmic" ? 12 : vibe === "candy" ? 14 : vibe === "mint" ? 11 : P.accent2;
      const turfMid = vibe === "cosmic" ? 28 : vibe === "candy" ? 15 : vibe === "mint" ? 3 : P.accent1;
      g.rect(0, GROUND_Y, 320, 40, vibe === "cosmic" ? 17 : 18);
      g.rect(0, GROUND_Y, 320, 6, turfMid);
      g.rect(0, GROUND_Y, 320, 2, turfTop);
      for (let i = 0; i < 12; i++) {
        const tx = ((i * 32 - (scrollX | 0)) % 352 + 352) % 352 - 16;
        g.rect(tx, GROUND_Y + 12, 12, 3, vibe === "cosmic" ? 12 : 4);
        g.rect(tx + 14, GROUND_Y + 22, 8, 2, P.fg);
      }
      for (const s of stars) {
        g.spr(((engine.frame >> 3) & 1) ? coin1 : coin2, s.x, s.y, { scale: 2 });
      }
      for (const o of obstacles) {
        if (o.kind === 2) {
          g.spr(((engine.frame >> 2) & 1) ? drone1 : drone2, o.x, o.y, { scale: 2 });
        } else if (o.kind === 1) {
          g.spr(crateSpr, o.x, GROUND_Y - 20, { scale: 2 });
          g.spr(crateSpr, o.x, GROUND_Y - 40, { scale: 2 });
        } else {
          g.spr(((engine.frame >> 2) & 1) ? boulder1 : boulder2, o.x, o.y, { scale: 2 });
        }
      }
      for (const gh of ghosts) g.spr(heroJump, gh.x, gh.y, { scale: 2 });
      if (inv <= 0 || engine.frame % 6 < 3) {
        const hSpr = y < GROUND_Y - 27 ? heroJump : (((engine.frame / 5) | 0) % 2 === 0 ? heroRun1 : heroRun2);
        g.spr(hSpr, 44, y, { scale: 2 });
      }
      for (const p of particles) g.rect(p.x, p.y, 2, 2, p.col);
      for (const pop of popups) g.text(pop.txt, pop.x, pop.y, pop.col, { align: "center" });
      engine.hud(g);
    },
  };
}

export function create(engine, card) {
  const P = card?.engine_palette || { bg: 17, fg: 28, accent1: 12, accent2: 14, ui: 7 };
  const heroName = String(card?.hero?.short || "SHIP").slice(0, 10).toUpperCase();

  // 11x10 6-color dark-outlined starfighter (2-frame thruster animation)
  const shipPal = { o: 16, c: P.accent1, b: P.fg, w: 7, f: 9, y: P.accent2 };
  const ship1 = engine.sprite([".....o.....","....owo....","...ocwco...","..ocwwwco..",".obcwwwcbo.","obbcwwwcbbo","obwwwwwwwbo","obbyyyyybbo",".oo.ofo.oo.","....oyo...."].join("\n"), shipPal);
  const ship2 = engine.sprite([".....o.....","....owo....","...ocwco...","..ocwwwco..",".obcwwwcbo.","obbcwwwcbbo","obwwwwwwwbo","obbyyyyybbo",".oo.oyo.oo.","...of.fo..."].join("\n"), shipPal);

  // 2-frame pulsing space jelly, kamikaze diver, 15x11 Armored Dreadnought Mini-Boss
  const jellyPal = { o: 16, f: P.fg, c: P.accent2, w: 7, k: 16 };
  const jelly1 = engine.sprite(["..ooooooo..",".offwwwffo.","offfffffffo","offwkffkwfo","occccccccco",".oc.ccc.co.",".o..o.o..o.","...o...o..."].join("\n"), jellyPal);
  const jelly2 = engine.sprite(["..ooooooo..",".offwwwffo.","offfffffffo","offwkffkwfo","occccccccco",".occ.c.cco.","..o..o..o..",".o.......o."].join("\n"), jellyPal);
  const diverSpr = engine.sprite(["...oyo...","..offfo..",".orrrrro.","orrwwwrro","orrrwrrro",".orrrrro.","..or.ro..","..o...o..","...o.o..."].join("\n"), { o: 16, r: 8, f: 9, y: P.accent2, w: 7 });
  const bossSpr = engine.sprite([
    "..ooooooooooo..", ".obbbbbbbbbbbo.", "obbccyyyyyccbbo", "obcwwrrrrrwwcbo",
    "obcwrrrrrrrwcbo", "obbbbbbbbbbbbbo", ".obyybbbbbbybo.", ".ob.obbbbbo.bo.",
    "..o..ob.bo..o..", ".....o...o.....", ".....oo.oo.....",
  ].join("\n"), { o: 16, b: P.fg, c: P.accent1, y: P.accent2, r: 8, w: 7 });
  const cellSpr = engine.sprite(["..oooo..",".occcco.","ocwwwwco","ocwwwwco",".occcco.","..oooo.."].join("\n"), { o: 16, c: P.accent2, w: 7 });

  let x = 149, y = 166, lives = 3, inv = 0, fireCd = 0, spreadTimer = 0;
  let waveTimer = 1.6, cellTimer = 2.0, waveNum = 1, waveCleared = false, empRadius = 0, empCd = 0;
  let bullets = [], eBullets = [], particles = [], popups = [], cells = [{ x: 152, y: 72, vy: 42 }];
  let enemies = [
    { x: 150, baseX: 150, y: 24, vy: 26, phase: 0, hp: 1, maxHp: 1, kind: 0, fireCd: 1.5, flash: 0 },
    { x: 104, baseX: 104, y: 16, vy: 28, phase: 1.5, hp: 1, maxHp: 1, kind: 0, fireCd: 1.9, flash: 0 },
    { x: 196, baseX: 196, y: 16, vy: 28, phase: 3.0, hp: 1, maxHp: 1, kind: 0, fireCd: 2.2, flash: 0 },
  ];
  engine.lives(lives);

  function explode(px, py, col, n) {
    for (let i = 0; i < n; i++) {
      const ang = engine.rng() * 6.283, spd = 20 + engine.rng() * 80;
      particles.push({ x: px, y: py, vx: Math.cos(ang) * spd, vy: Math.sin(ang) * spd, life: 0.2 + engine.rng() * 0.25, col });
    }
  }
  function addPopup(txt, px, py, col) {
    popups.push({ txt, x: Math.max(28, Math.min(292, px)), y: py, col, life: 0.6 });
  }

  return {
    update(dt, input) {
      x = Math.max(8, Math.min(290, x + ((input.right ? 1 : 0) - (input.left ? 1 : 0)) * 140 * dt));
      y = Math.max(40, Math.min(176, y + ((input.down ? 1 : 0) - (input.up ? 1 : 0)) * 135 * dt));
      if (spreadTimer > 0) spreadTimer -= dt;
      if (inv > 0) inv -= dt;
      if (empCd > 0) empCd -= dt;

      if (input.pressed.b && empCd <= 0) {
        empCd = 3.2; empRadius = 6;
        engine.sfx("powerup"); engine.shake(4, 1); addPopup("EMP PULSE", x + 11, y - 6, 12);
      }
      if (empRadius > 0) {
        empRadius += 230 * dt;
        eBullets = eBullets.filter((eb) => {
          if (Math.hypot(eb.x - (x + 11), eb.y - (y + 10)) <= empRadius + 6) {
            engine.score(2); explode(eb.x, eb.y, 12, 3); return false;
          }
          return true;
        });
        if (empRadius > 88) empRadius = 0;
      }

      fireCd -= dt;
      const activeMove = input.a || input.b || input.left || input.right || input.up || input.down;
      if (fireCd <= 0 && activeMove) {
        bullets.push({ x: x + 11, y: y - 4, vx: 0, vy: -245 });
        if (spreadTimer > 0) bullets.push({ x: x + 5, y: y - 2, vx: -58, vy: -230 }, { x: x + 17, y: y - 2, vx: 58, vy: -230 });
        fireCd = 0.16; engine.sfx("shoot");
      }
      for (const b of bullets) { b.x += b.vx * dt; b.y += b.vy * dt; }
      bullets = bullets.filter((b) => b.y > -10 && b.x > -10 && b.x < 330);

      waveTimer -= dt;
      if (waveTimer <= 0) {
        waveNum++; waveCleared = false;
        if (waveNum % 3 === 0) enemies.push({ x: 145, baseX: 145, y: -18, vy: 28, phase: 0, hp: 5, maxHp: 5, kind: 2, fireCd: 1.1, flash: 0 });
        const count = 2 + (engine.time > 14 ? 1 : 0), startX = engine.rngInt(36, 240);
        for (let i = 0; i < count; i++) {
          const ex = Math.max(20, Math.min(268, startX + (i - 1) * 44));
          const isDiver = engine.time > 10 && i === count - 1 && waveNum % 2 === 0;
          enemies.push({ x: ex, baseX: ex, y: -14 - i * 12, vy: isDiver ? 78 : 30 + Math.min(42, engine.time * 1.1), phase: engine.rng() * 6.28, hp: 1, maxHp: 1, kind: isDiver ? 1 : 0, fireCd: 0.9 + engine.rng() * 1.0, flash: 0 });
        }
        waveTimer = Math.max(0.95, 1.85 - engine.time * 0.014);
      }

      cellTimer -= dt;
      if (cellTimer <= 0) {
        cells.push({ x: engine.rngInt(24, 286), y: -10, vy: 45 });
        cellTimer = 3.2 + engine.rng() * 1.5;
      }
      for (const c of cells) c.y += c.vy * dt;
      cells = cells.filter((c) => {
        if (Math.abs(c.x - (x + 7)) < 15 && Math.abs(c.y - (y + 7)) < 15) {
          engine.score(25); spreadTimer = 6.0; engine.sfx("powerup");
          explode(c.x, c.y, P.accent2, 8); addPopup("SPREAD +25", c.x, c.y, P.accent2);
          return false;
        }
        return c.y < 208;
      });

      for (const e of enemies) {
        if (e.flash > 0) e.flash -= dt;
        if (e.kind === 2) {
          if (e.y < 30) e.y += e.vy * dt;
          else e.y += 6 * dt;
          e.x = Math.max(16, Math.min(274, 145 + Math.sin(engine.time * 2.0 + e.phase) * 76));
        } else if (e.kind === 1) {
          e.y += e.vy * dt;
          e.x += Math.sign(x - e.x) * 62 * dt;
        } else {
          e.y += e.vy * dt;
          e.x = Math.max(12, Math.min(284, e.baseX + Math.sin(engine.time * 3 + e.phase) * 24));
        }
        e.fireCd -= dt;
        if (e.fireCd <= 0 && e.y > 14 && e.y < 142 && e.kind !== 1) {
          const dx = (x + 8) - (e.x + 8), dy = Math.max(36, (y + 8) - (e.y + 8));
          const len = Math.hypot(dx, dy) || 1, bspd = 92 + Math.min(48, engine.time);
          const vx = (dx / len) * bspd, vy = (dy / len) * bspd;
          eBullets.push({ x: e.x + 11, y: e.y + 12, vx, vy });
          if (e.kind === 2) {
            eBullets.push({ x: e.x + 6, y: e.y + 12, vx: vx - 34, vy }, { x: e.x + 18, y: e.y + 12, vx: vx + 34, vy });
          }
          e.fireCd = e.kind === 2 ? 1.15 : Math.max(0.9, 2.0 - engine.time * 0.01);
        }
      }

      for (const e of enemies) {
        const hitW = e.kind === 2 ? 16 : 11, hitH = e.kind === 2 ? 12 : 10;
        for (const b of bullets) {
          if (e.hp > 0 && b.y > -50 && Math.abs(b.x - (e.x + hitW - 2)) < hitW && Math.abs(b.y - (e.y + 8)) < hitH) {
            e.hp--; e.flash = 0.1; b.y = -99;
            if (e.hp <= 0) {
              const pts = e.kind === 2 ? 100 : e.kind === 1 ? 25 : 15;
              engine.score(pts); engine.sfx("explode");
              explode(e.x + 10, e.y + 8, e.kind === 2 ? 8 : P.accent1, e.kind === 2 ? 16 : 10);
              if (e.kind === 2) {
                engine.shake(6, 2); cells.push({ x: e.x + 8, y: e.y + 6, vy: 46 });
                addPopup("BOSS +100", e.x + 14, e.y, P.accent2);
              } else if (engine.rng() < 0.25) {
                cells.push({ x: e.x + 4, y: e.y + 4, vy: 48 });
              }
            } else {
              engine.sfx("hit");
            }
          }
        }
      }

      function hitPlayer() {
        if (inv > 0) return;
        lives--; inv = 1.5;
        engine.lives(lives); engine.sfx("hit"); engine.shake(8, 2);
        explode(x + 10, y + 8, P.fg, 10);
        if (lives <= 0) engine.gameOver(`${heroName} LOST`);
      }

      for (const e of enemies) {
        if (inv <= 0 && e.hp > 0 && Math.abs((e.x + 10) - (x + 10)) < 13 && Math.abs((e.y + 8) - (y + 8)) < 12) {
          e.hp -= e.kind === 2 ? 1 : 99; hitPlayer();
        }
      }
      const killedOnFrame = enemies.some((e) => e.hp <= 0);
      enemies = enemies.filter((e) => e.hp > 0 && e.y < 210);
      if (killedOnFrame && enemies.length === 0 && !waveCleared) {
        waveCleared = true; engine.score(50);
        addPopup("WAVE CLEAR +50", 160, 86, P.accent2);
      }

      for (const eb of eBullets) { eb.x += eb.vx * dt; eb.y += eb.vy * dt; }
      eBullets = eBullets.filter((eb) => {
        if (Math.abs(eb.x - (x + 10)) < 8 && Math.abs(eb.y - (y + 9)) < 8) {
          hitPlayer(); return false;
        }
        return eb.y < 208 && eb.y > -10 && eb.x > -10 && eb.x < 330;
      });

      for (const p of particles) { p.x += p.vx * dt; p.y += p.vy * dt; p.life -= dt; }
      particles = particles.filter((p) => p.life > 0);
      for (const pop of popups) { pop.y -= 22 * dt; pop.life -= dt; }
      popups = popups.filter((pop) => pop.life > 0);
    },

    draw(g) {
      g.cls(16);
      g.dither(0, 0, 320, 72, 16, P.bg, 1);
      g.dither(0, 72, 320, 72, P.bg, 17, 1);
      g.dither(0, 144, 320, 56, 17, P.fg, 1);
      g.circ(248, 56, 22, P.fg);
      g.circ(248, 56, 16, P.accent2);
      g.line(218, 62, 278, 50, P.accent1);

      for (let i = 0; i < 32; i++) {
        const sx = (i * 73) % 320, spd = (i % 3) + 1;
        const sy = ((i * 41 + engine.frame * spd) % 200) | 0;
        g.pset(sx, sy, spd === 3 ? 7 : P.accent1);
      }

      for (const c of cells) g.spr(cellSpr, c.x, c.y, { scale: 2 });
      for (const e of enemies) {
        const spr = e.kind === 2 ? bossSpr : e.kind === 1 ? diverSpr : (((engine.frame >> 3) & 1) ? jelly1 : jelly2);
        g.spr(spr, e.x, e.y, { scale: 2, flash: e.flash > 0 ? 7 : undefined });
        if (e.kind === 2) {
          g.rect(e.x, e.y - 5, 30, 3, 16);
          g.rect(e.x, e.y - 5, Math.round((30 * e.hp) / e.maxHp), 3, e.flash > 0 ? 7 : 8);
        }
      }

      for (const b of bullets) g.rect(b.x - 1, b.y, 2, 6, P.accent2);
      for (const eb of eBullets) {
        g.circ(eb.x, eb.y, 2, 8);
        g.pset(eb.x, eb.y, 7);
      }
      if (empRadius > 0) {
        g.circb(x + 11, y + 10, empRadius | 0, 12);
        g.circb(x + 11, y + 10, Math.max(1, (empRadius - 3) | 0), 7);
      }
      if (inv <= 0 || engine.frame % 6 < 3) {
        g.spr(((engine.frame >> 2) & 1) ? ship1 : ship2, x, y, { scale: 2 });
      }
      for (const p of particles) g.rect(p.x, p.y, 2, 2, p.col);
      for (const pop of popups) g.text(pop.txt, pop.x, pop.y, pop.col, { align: "center" });
      engine.hud(g);
    },
  };
}

export function create(engine, card) {
  const P = card?.engine_palette || { bg: 19, fg: 27, accent1: 11, accent2: 15, ui: 7 };
  const heroName = String(card?.hero?.short || "MOTH").toUpperCase();
  const heroPal = { o: 16, w: 7, b: P.fg, p: P.accent1, a: P.accent2, s: 12 };
  const hero1 = engine.sprite("..o.a..a.o..\n.obbboobbbo.\nobwwbppbwwbo\nobpbbaabbpbo\nobbbowwobbbo\n.obpsaaaspbo\n.obbbaabbbbo\n..obbpbbpbo.\n...oo.oo.o..\n....o..o....", heroPal);
  const hero2 = engine.sprite("....a..a....\n...oo..oo...\n..obboobbo..\n.obwwaawwbo.\nobpbbaabbpbo\nobbbowwobbbo\nobpsbaaaspbo\n.obbbaabbbbo\n..obbpbbpbo.\n...oo..oo...", heroPal);

  const mkGhost = (f) => [
    engine.sprite("..oooooo..\n.ohfffffo.\noffwffwffo\noffwffwffo\noffffffffo\noffsssfffo\nof.offo.fo\no..o..o..o", { o: 16, f, h: 7, s: P.bg, w: 7 }),
    engine.sprite("..oooooo..\n.ohfffffo.\noffwffwffo\noffwffwffo\noffffffffo\noffsssfffo\n.fo.oo.of.\n..o....o..", { o: 16, f, h: 7, s: P.bg, w: 7 }),
  ];
  const [ghostSpr1, ghostSpr2] = mkGhost(P.fg);
  const ghostSets = [[ghostSpr1, ghostSpr2], mkGhost(P.accent1), mkGhost(P.accent2)];
  const scaredSpr1 = engine.sprite("..oooooo..\n.occcccco.\noccwccwcco\nocccccccco\noc.wc.wcco\nocw.ww.wco\noc.occo.co\no..o..o..o", { o: 16, c: 12, w: 7 });
  const scaredSpr2 = engine.sprite("..oooooo..\n.owwwwwwo.\nowwrwwrwwo\nowwwwwwwwo\now.rw.rwwo\nowr.rr.rwo\n.wo.oo.ow.\n..o....o..", { o: 16, w: 7, r: 8 });
  const gemSpr = engine.sprite("...oooo...\n..ocwwco..\n.ocwwwwco.\nocwccccaco\n.ocaaacco.\n..occcco..\n...oooo...", { o: 16, c: P.accent2, a: P.accent1, w: 7 });

  const LAYOUTS = [
    [
      "###################", "#o.......#.......o#", "#.##.###.#.###.##.#", "#.................#",
      "#.##.#.#####.#.##.#", ".....#...G...#.....", "####.###.#.###.####", "#.................#",
      "#.##.###.#.###.##.#", "#o.......S.......o#", "###################",
    ],
    [
      "###################", "#o...#.......#...o#", "#.##.#.#####.#.##.#", "#....#...#...#....#",
      "###.####.#.####.###", ".....#...G...#.....", "###.####.#.####.###", "#....#.......#....#",
      "#.##.#.#####.#.##.#", "#o.......S.......o#", "###################",
    ],
  ];

  const COLS = 19, ROWS = 11, TS = 14, OX = 27, OY = 24;
  let stage = 1, layout = LAYOUTS[0], dots = [], totalDots = 0, maxDots = 0;
  let bonusActive = false, bonusSpawned = false, frightCombo = 0, sparks = [], popups = [];

  function burst(x, y, col, n = 8) {
    for (let i = 0; i < n; i++) {
      const a = (i / n) * 6.28 + engine.rng() * 0.5;
      sparks.push({ x, y, vx: Math.cos(a) * 55, vy: Math.sin(a) * 55, life: 0.3, col });
    }
  }
  const addPopup = (txt, x, y, col = 7) => popups.push({ txt, x, y, col, life: 0.65 });

  function buildDots() {
    layout = LAYOUTS[(stage - 1) % LAYOUTS.length];
    dots = []; totalDots = 0; bonusActive = false; bonusSpawned = false;
    for (let r = 0; r < ROWS; r++) {
      const row = [];
      for (let c = 0; c < COLS; c++) {
        const ch = layout[r][c];
        const v = ch === "." ? 1 : ch === "o" ? 2 : 0;
        if (v > 0) totalDots++;
        row.push(v);
      }
      dots.push(row);
    }
    maxDots = totalDots;
  }
  buildDots();

  const isWall = (c, r) => {
    if (r < 0 || r >= ROWS) return true;
    if (r === 5 && (c < 0 || c >= COLS)) return false;
    return c < 0 || c >= COLS || layout[r][c] === "#";
  };
  const tileCenter = (c, r) => ({ x: OX + c * TS + TS / 2, y: OY + r * TS + TS / 2 });

  const startPos = tileCenter(9, 9), gemPos = tileCenter(9, 5);
  let hx = startPos.x, hy = startPos.y, dirX = 1, dirY = 0;
  let lives = 3, inv = 0, fright = 0, dashTimer = 0, dashCd = 0;

  function makeGhosts() {
    const g0 = tileCenter(1, 1), g1 = tileCenter(17, 1), g2 = tileCenter(8, 1);
    return [
      { x: g0.x, y: g0.y, vx: 1, vy: 0, homeC: 1, homeR: 1, role: 0, active: true },
      { x: g1.x, y: g1.y, vx: -1, vy: 0, homeC: 17, homeR: 1, role: 1, active: true },
      { x: g2.x, y: g2.y, vx: 1, vy: 0, homeC: 8, homeR: 1, role: 2, active: stage > 1 || engine.time > 8 },
    ];
  }
  let ghosts = makeGhosts();
  engine.lives(lives);

  const canMove = (px, py, dx, dy) =>
    !isWall(Math.floor((px + dx * 5 - OX) / TS), Math.floor((py + dy * 5 - OY) / TS));

  return {
    update(dt, input) {
      if (inv > 0) inv -= dt;
      if (fright > 0) fright -= dt;
      if (dashTimer > 0) dashTimer -= dt;
      if (dashCd > 0) dashCd -= dt;

      if ((input.pressed.a || input.pressed.b) && dashCd <= 0) {
        dashTimer = 0.22; dashCd = 1.8; engine.sfx("jump"); burst(hx, hy, P.accent2, 6);
      }

      let wantX = (input.right ? 1 : 0) - (input.left ? 1 : 0);
      let wantY = (input.down ? 1 : 0) - (input.up ? 1 : 0);
      if ((input.a || dashTimer > 0) && wantX === 0 && wantY === 0) { wantX = dirX; wantY = dirY; }

      const spd = (dashTimer > 0 ? 132 : 76) * dt;
      const curC = Math.max(0, Math.min(COLS - 1, Math.floor((hx - OX) / TS)));
      const curR = Math.max(0, Math.min(ROWS - 1, Math.floor((hy - OY) / TS)));
      const center = tileCenter(curC, curR);

      if (wantX !== 0 && !isWall(curC + wantX, curR) && Math.abs(hy - center.y) < 6) {
        hy += (center.y - hy) * 0.45; dirX = wantX; dirY = 0;
      } else if (wantY !== 0 && !isWall(curC, curR + wantY) && Math.abs(hx - center.x) < 6) {
        hx += (center.x - hx) * 0.45; dirX = 0; dirY = wantY;
      }

      if (wantX !== 0 || wantY !== 0 || input.a || dashTimer > 0) {
        if (canMove(hx + dirX * spd, hy + dirY * spd, dirX, dirY)) {
          hx += dirX * spd; hy += dirY * spd;
          if (dashTimer > 0 && engine.frame % 2 === 0) {
            sparks.push({ x: hx, y: hy, vx: -dirX * 20, vy: -dirY * 20, life: 0.18, col: 7 });
          }
        } else {
          hx += (center.x - hx) * 0.3; hy += (center.y - hy) * 0.3;
        }
      }
      if (hx < OX + 2) hx = OX + COLS * TS - 3;
      else if (hx > OX + COLS * TS - 2) hx = OX + 3;

      const hc = Math.floor((hx - OX) / TS), hr = Math.floor((hy - OY) / TS);
      if (hr >= 0 && hr < ROWS && hc >= 0 && hc < COLS && dots[hr][hc] > 0) {
        const kind = dots[hr][hc];
        dots[hr][hc] = 0; totalDots--;
        if (!bonusSpawned && totalDots <= (maxDots >> 1)) { bonusActive = true; bonusSpawned = true; }
        if (kind === 2) {
          fright = 6.0; frightCombo = 0; engine.score(25); engine.sfx("powerup"); burst(hx, hy, P.accent1, 8);
        } else {
          engine.score(10); engine.sfx("coin");
        }
        if (totalDots <= 0) {
          stage++; engine.score(100); engine.sfx("win"); addPopup("STAGE " + stage, 160, 96, P.accent2);
          buildDots(); hx = startPos.x; hy = startPos.y; dirX = 1; dirY = 0; ghosts = makeGhosts();
        }
      }
      if (bonusActive && Math.hypot(hx - gemPos.x, hy - gemPos.y) < 10) {
        bonusActive = false; engine.score(75); engine.sfx("powerup");
        burst(gemPos.x, gemPos.y, P.accent2, 10); addPopup("+75", gemPos.x, gemPos.y - 6, P.accent2);
      }

      if (engine.time > 8) ghosts[2].active = true;
      const gSpd = (fright > 0 ? 42 : 62 + Math.min(25, engine.time * 0.5)) * dt;
      for (const gh of ghosts) {
        if (!gh.active) continue;
        const gc = Math.max(0, Math.min(COLS - 1, Math.floor((gh.x - OX) / TS)));
        const gr = Math.max(0, Math.min(ROWS - 1, Math.floor((gh.y - OY) / TS)));
        const tileId = gr * COLS + gc, gCen = tileCenter(gc, gr);
        const blocked = isWall(gc + gh.vx, gr + gh.vy), distCen = Math.hypot(gh.x - gCen.x, gh.y - gCen.y);
        const passedCen = (gh.x - gCen.x) * gh.vx + (gh.y - gCen.y) * gh.vy >= 0;
        if (gh.lastTile !== tileId && (distCen < 2.4 || (blocked && passedCen))) {
          gh.lastTile = tileId;
          const dirs = [{ vx: 1, vy: 0 }, { vx: -1, vy: 0 }, { vx: 0, vy: 1 }, { vx: 0, vy: -1 }]
            .filter((d) => !isWall(gc + d.vx, gr + d.vy));
          const nonRev = dirs.filter((d) => !(d.vx === -gh.vx && d.vy === -gh.vy));
          const pool = nonRev.length > 0 ? nonRev : dirs;
          if (pool.length > 0) {
            const distHero = Math.hypot(gh.x - hx, gh.y - hy);
            const tx = gh.role === 1 && distHero > 42 ? hx + dirX * TS * 3 : gh.role === 2 && ((engine.time | 0) % 6 < 2) ? 160 : hx;
            const ty = gh.role === 1 && distHero > 42 ? hy + dirY * TS * 3 : gh.role === 2 && ((engine.time | 0) % 6 < 2) ? 60 : hy;
            pool.sort((a, b) => {
              const da = Math.hypot(OX + (gc + a.vx) * TS - tx, OY + (gr + a.vy) * TS - ty);
              const db = Math.hypot(OX + (gc + b.vx) * TS - tx, OY + (gr + b.vy) * TS - ty);
              return fright > 0 ? db - da : da - db;
            });
            const pick = engine.rng() < 0.82 ? pool[0] : pool[engine.rngInt(0, pool.length - 1)];
            gh.vx = pick.vx; gh.vy = pick.vy; gh.x = gCen.x; gh.y = gCen.y;
          }
        }
        gh.x += gh.vx * gSpd; gh.y += gh.vy * gSpd;
        if (gh.x < OX + 2) gh.x = OX + COLS * TS - 3;
        else if (gh.x > OX + COLS * TS - 2) gh.x = OX + 3;

        if (Math.hypot(gh.x - hx, gh.y - hy) < 9) {
          if (fright > 0) {
            frightCombo = Math.min(3, frightCombo + 1);
            const pts = frightCombo * 50;
            engine.score(pts); engine.sfx("explode");
            burst(gh.x, gh.y, 12, 10); addPopup("+" + pts, gh.x, gh.y - 6, 7);
            const home = tileCenter(gh.homeC, gh.homeR);
            gh.x = home.x; gh.y = home.y; gh.lastTile = -1;
          } else if (inv <= 0) {
            lives--; inv = 1.8; engine.lives(lives); engine.sfx("hit"); engine.shake(8, 2);
            burst(hx, hy, 8, 10); ghosts = makeGhosts();
            if (lives <= 0) engine.gameOver(heroName + " CAUGHT");
            break;
          }
        }
      }
      for (const s of sparks) { s.x += s.vx * dt; s.y += s.vy * dt; s.life -= dt; }
      sparks = sparks.filter((s) => s.life > 0);
      for (const p of popups) { p.y -= 18 * dt; p.life -= dt; }
      popups = popups.filter((p) => p.life > 0);
    },

    draw(g) {
      g.dither(0, 0, 320, 200, 17, P.bg, 1);
      for (let r = 0; r < ROWS; r++) {
        for (let c = 0; c < COLS; c++) {
          const tx = OX + c * TS, ty = OY + r * TS;
          if (layout[r][c] === "#") {
            g.rect(tx, ty, TS, TS, 16);
            g.rect(tx + 1, ty + 1, TS - 2, TS - 2, P.fg);
            g.rect(tx + 2, ty + 2, TS - 4, 2, P.accent1);
          } else if (dots[r][c] === 1) {
            g.rect(tx + 5, ty + 5, 3, 3, P.accent2);
            g.pset(tx + 5, ty + 5, 7);
          } else if (dots[r][c] === 2 && engine.frame % 16 < 12) {
            g.circ(tx + 7, ty + 7, 4, P.accent1);
            g.circ(tx + 7, ty + 7, 2, 7);
          }
        }
      }
      if (bonusActive) g.spr(gemSpr, gemPos.x - 5, gemPos.y - 4 + ((engine.frame >> 3) & 1));
      const hSpr = (engine.frame >> 2) & 1 ? hero2 : hero1;
      if (inv <= 0 || engine.frame % 6 < 3) g.spr(hSpr, hx - 6, hy - 5, { flipX: dirX < 0 });
      for (const gh of ghosts) {
        if (!gh.active) continue;
        const anim = (engine.frame >> 3) & 1;
        const spr = fright > 0 ? (fright < 1.8 && (engine.frame >> 2) & 1 ? scaredSpr2 : scaredSpr1) : ghostSets[gh.role][anim];
        g.spr(spr, gh.x - 5, gh.y - 4);
        if (fright <= 0) {
          g.pset(gh.x - 2 + gh.vx, gh.y - 1 + gh.vy, 16);
          g.pset(gh.x + 1 + gh.vx, gh.y - 1 + gh.vy, 16);
        }
      }
      for (const s of sparks) g.rect(s.x, s.y, 2, 2, s.col);
      for (const p of popups) g.text(p.txt, p.x, p.y, p.col, { align: "center" });
      engine.hud(g);
    },
  };
}

export function create(engine, card) {
  const P = card?.engine_palette || { bg: 18, fg: 14, accent1: 15, accent2: 10, ui: 7 };
  const heroName = String(card?.hero?.short || "CUPCAKE").toUpperCase();
  const heroPal = { o: 16, k: 16, r: 8, w: 7, p: P.accent1, b: P.fg, t: P.accent2 };
  const hero1 = engine.sprite("....ooo....\n...orwro...\n..oopppoo..\n.opwpwpwpo.\nopptppptppo\nooooooooooo\nobwtbtbtwbo\nobokbtbkobo\n.obtbtbtbo.\n..ooooooo..", heroPal);
  const hero2 = engine.sprite("....ooo....\n...orrwo...\n..oopppoo..\n.opppwpppo.\noptppppptpo\nooooooooooo\nobtbtbtbtbo\nobtkbtbktbo\n.obtbtbtbo.\n..ooooooo..", heroPal);
  const dropMSpr = engine.sprite(".ooooooo.\nocwcccwco\nocwwcwwco\nocwcwcwco\nocwcccwco\noccccccco\n.ooooooo.", { o: 16, c: P.accent2, w: 7 });
  const dropWSpr = engine.sprite(".ooooooo.\nocwcccwco\nocwcccwco\nocwcwcwco\nocwwcwwco\noccccccco\n.ooooooo.", { o: 16, c: P.accent1, w: 7 });

  const COLS = 8, ROWS = 6, BW = 32, BH = 9, GAP = 3, OX = 22, OY = 28;
  const ROW_COLS = [P.ui, P.fg, P.accent1, P.accent2, P.fg, P.accent1];
  let stage = 1, bricks = [], drops = [], sparks = [], popups = [], combo = 0;

  function buildBricks() {
    bricks = [];
    const pat = (stage - 1) % 3;
    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        if (pat === 1 && r > 0 && r < 5 && (c === 3 || c === 4)) continue;
        if (pat === 2 && ((r + c) % 5 === 1) && r < 4) continue;
        const armored = r === 0 || (pat > 0 && r === 1 && (c + r) % 2 === 0);
        const hp = armored ? 2 : 1;
        bricks.push({
          x: OX + c * (BW + GAP), y: OY + r * (BH + GAP), w: BW, h: BH,
          col: armored ? 6 : ROW_COLS[r % ROW_COLS.length], hp, maxHp: hp, flash: 0, alive: true,
        });
      }
    }
  }
  buildBricks();

  let px = 136, wideTimer = 0, lives = 3, launchWait = 1.4, smashWin = 0;
  const py = 184;
  let balls = [{ x: 160, y: 178, vx: 78, vy: -145, stuck: true, pierce: 0 }];
  engine.lives(lives);

  function addSparks(sx, sy, col, n = 6) {
    for (let i = 0; i < n; i++) {
      sparks.push({ x: sx, y: sy, vx: (engine.rng() - 0.5) * 95, vy: (engine.rng() - 0.5) * 95, life: 0.24, col });
    }
  }
  const addPopup = (txt, x, y, col = 7) => popups.push({ txt, x, y, col, life: 0.6 });

  return {
    update(dt, input) {
      const pw = wideTimer > 0 ? 64 : 46;
      if (wideTimer > 0) wideTimer -= dt;
      if (smashWin > 0) smashWin -= dt;
      if (input.pressed.a || input.pressed.b || input.pressed.up) smashWin = 0.25;

      const move = (input.right ? 1 : 0) - (input.left ? 1 : 0);
      px = Math.max(12, Math.min(308 - pw, px + move * 185 * dt));

      const launchKey = input.a || input.b || input.up || input.left || input.right || input.pressed.start;
      if (balls.some((b) => b.stuck)) {
        launchWait -= dt;
        const canManual = lives === 3 || launchWait < 1.1;
        for (const b of balls) {
          if (b.stuck) {
            b.x = px + pw / 2; b.y = py - 5;
            if ((launchKey && canManual) || launchWait <= 0) {
              b.stuck = false; b.vx = 85; b.vy = -148; b.pierce = 0; combo = 0;
              engine.sfx("select");
            }
          }
        }
      }

      for (const br of bricks) if (br.flash > 0) br.flash -= dt;

      for (const b of balls) {
        if (b.stuck) continue;
        b.x += b.vx * dt; b.y += b.vy * dt;

        if (b.x < 14) { b.x = 14; b.vx = Math.abs(b.vx); }
        else if (b.x > 306) { b.x = 306; b.vx = -Math.abs(b.vx); }
        if (b.y < 20) { b.y = 20; b.vy = Math.abs(b.vy); }

        if (b.vy > 0 && b.y + 3 >= py && b.y - 3 <= py + 7 && b.x + 3 >= px && b.x - 3 <= px + pw) {
          const hitOffset = (b.x - (px + pw / 2)) / (pw / 2);
          const adj = Math.abs(hitOffset) < 0.08 ? 0.35 : hitOffset;
          const smash = smashWin > 0;
          const spd = Math.min(220, Math.hypot(b.vx, b.vy) * (smash ? 1.1 : 1.02));
          b.vx = adj * spd * 0.78;
          b.vy = -Math.sqrt(Math.max(8500, spd * spd - b.vx * b.vx));
          b.y = py - 4; combo = 0;
          if (smash) {
            b.pierce = 1; smashWin = 0; engine.shake(3, 1);
            addSparks(b.x, py, 7, 8); addPopup("SMASH!", b.x, py - 14, 7);
          }
          engine.score(2); engine.sfx("jump");
        }

        for (const br of bricks) {
          if (!br.alive) continue;
          if (b.x + 3 > br.x && b.x - 3 < br.x + br.w && b.y + 3 > br.y && b.y - 3 < br.y + br.h) {
            combo++;
            const cx = br.x + br.w / 2, cy = br.y + br.h / 2;
            if (b.pierce > 0) {
              br.alive = false; b.pierce--;
              const pts = br.maxHp === 2 ? 25 : Math.min(30, combo * 10);
              engine.score(pts); engine.sfx("explode");
              addSparks(cx, cy, 7, 9); addPopup("+" + pts, cx, br.y, 7);
            } else if (br.hp > 1) {
              br.hp--; br.flash = 0.14; b.vy = -b.vy;
              engine.score(10); engine.sfx("hit"); addSparks(cx, cy, 7, 5);
            } else {
              br.alive = false; b.vy = -b.vy;
              const pts = br.maxHp === 2 ? 25 : Math.min(30, combo * 10);
              engine.score(pts); engine.sfx("coin");
              addSparks(cx, cy, br.col, 7); addPopup("+" + pts, cx, br.y, br.maxHp === 2 ? 7 : P.accent2);
            }
            if (!br.alive && engine.rng() < 0.3) {
              drops.push({ x: cx - 8, y: br.y + 4, vy: 68, kind: engine.rng() < 0.5 ? "multi" : "wide" });
            }
            break;
          }
        }
      }

      if (bricks.every((br) => !br.alive)) {
        stage++; engine.score(100); engine.sfx("win");
        addPopup("STAGE " + stage, 160, 100, P.accent2); buildBricks();
        for (const b of balls) { if (b.y < 108) { b.y = 108; b.vy = Math.abs(b.vy); } }
      }

      for (const d of drops) d.y += d.vy * dt;
      drops = drops.filter((d) => {
        if (d.y + 12 >= py && d.y <= py + 8 && d.x + 16 >= px && d.x <= px + pw) {
          engine.score(25); engine.sfx("powerup");
          if (d.kind === "multi" && balls.length < 3) {
            const src = balls[0] || { x: px + pw / 2, y: py - 8 };
            balls.push({ x: src.x, y: src.y, vx: -95, vy: -140, stuck: false, pierce: 0 });
            addPopup("MULTI!", px + pw / 2, py - 14, P.accent2);
          } else {
            wideTimer = 8.0; addPopup("WIDE!", px + pw / 2, py - 14, P.accent1);
          }
          return false;
        }
        return d.y < 204;
      });

      balls = balls.filter((b) => b.y < 198);
      if (balls.length === 0) {
        lives--; combo = 0; engine.lives(lives); engine.sfx("hit"); engine.shake(8, 2);
        if (lives <= 0) {
          engine.gameOver(heroName + " OUT OF BALLS");
        } else {
          launchWait = 2.0;
          balls = [{ x: px + pw / 2, y: py - 5, vx: 88, vy: -145, stuck: true, pierce: 0 }];
        }
      }

      for (const s of sparks) { s.x += s.vx * dt; s.y += s.vy * dt; s.life -= dt; }
      sparks = sparks.filter((s) => s.life > 0);
      for (const p of popups) { p.y -= 18 * dt; p.life -= dt; }
      popups = popups.filter((p) => p.life > 0);
    },

    draw(g) {
      g.dither(0, 0, 320, 100, 18, P.bg, 1);
      g.dither(0, 100, 320, 100, P.bg, 17, 1);
      g.rectb(10, 20, 300, 178, P.fg);

      for (const br of bricks) {
        if (!br.alive) continue;
        const fill = br.flash > 0 ? 7 : br.col;
        g.rect(br.x, br.y, br.w, br.h, 16);
        g.rect(br.x + 1, br.y + 1, br.w - 2, br.h - 2, fill);
        g.rect(br.x + 2, br.y + 1, br.w - 4, 2, 7);
        if (br.maxHp === 2) {
          g.pset(br.x + 3, br.y + 4, 16); g.pset(br.x + br.w - 4, br.y + 4, 16);
          if (br.hp === 1) {
            g.line(br.x + 9, br.y + 1, br.x + 15, br.y + 7, 16);
            g.line(br.x + 15, br.y + 7, br.x + 21, br.y + 2, 7);
          }
        }
      }

      for (const d of drops) g.spr(d.kind === "multi" ? dropMSpr : dropWSpr, d.x, d.y, { scale: 2 });

      const pw = wideTimer > 0 ? 64 : 46;
      g.rect(px, py, pw, 7, 16);
      g.rect(px + 1, py + 1, pw - 2, 5, P.accent1);
      g.rect(px + 2, py + 1, pw - 4, 2, 7);
      g.spr((engine.frame >> 4) & 1 ? hero2 : hero1, px + pw / 2 - 11, py - 15, { scale: 2 });

      for (const b of balls) {
        if (!b.stuck) {
          for (let i = 3; i >= 1; i--) {
            const tx = b.x - b.vx * 0.014 * i, ty = b.y - b.vy * 0.014 * i;
            g.circ(tx, ty, 4 - i, i === 1 ? 7 : i === 2 ? P.accent1 : P.fg);
          }
        }
        g.circ(b.x, b.y, 4, 16);
        g.circ(b.x, b.y, 3, b.pierce > 0 ? 7 : P.accent2);
        g.pset(b.x - 1, b.y - 1, 7);
      }

      for (const s of sparks) g.rect(s.x, s.y, 2, 2, s.col);
      for (const p of popups) g.text(p.txt, p.x, p.y, p.col, { align: "center" });
      engine.hud(g);
    },
  };
}

