      if (input.pressed.b && dashCd <= 0) {
        dashCd = 0.85; wallVx = (facingLeft ? -1 : 1) * 175;
        vy = Math.min(vy, -90); engine.sfx("jump"); burst(hx + 12, hy + 12, P.accent2, 6);
      }
      vx = move * 125 + wallVx;

      const wallDir = !grounded ? (hx <= 7 ? 1 : hx >= 287 ? -1 : 0) : 0;
      if (wallDir !== 0 && vy > 0) {
        vy = Math.min(vy, 45);
        if (engine.frame % 4 === 0) {
